/* BankAuctions Field · Android app for field verification engineers */
(function(){
var BA=window.BA,FV=window.FV,esc=BA.esc,$=function(i){return document.getElementById(i)};
var S={id:BA.ls('ba3_fapp')||'',tab:'home',sel:null,filter:'all',otp:false,ph:'',msg:''},inst=null;
BA.toast=function(m){var t=document.createElement('div');t.className='toast';t.textContent=m;$('dev').appendChild(t);setTimeout(function(){t.remove()},2600)};
window.addEventListener('beforeinstallprompt',function(e){e.preventDefault();inst=e;if(!me())login()});
function tick(){var d=new Date();$('clk').textContent=d.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',hour12:false})}tick();setInterval(tick,30000);
function me(){var m=S.id?FV.get(S.id):null;if(m&&(m.role!=='field'||m.status!=='active')){S.msg=m.status==='suspended'?'Your account is suspended. Contact Admin.':'Your account is deactivated. Contact Admin.';S.id='';BA.ls('ba3_fapp',null);return null}return m}
function bell(){var m=me();if(!m)return 0;var seen=+BA.ls('ba3_fseen_'+m.id)||0;return FV.notifs('eng:'+m.id).filter(function(n){return n.at>seen}).length}
/* ---------- chrome ---------- */
function chrome(title,back){var m=me(),b=$('bar');b.hidden=false;
 b.innerHTML=(back?'<button id="bk" aria-label="Back">←</button>':'<img src="img/app/icon-192.png" alt="" width="34" height="34" style="border-radius:9px">')+'<b>'+esc(title)+'</b><button id="bl" aria-label="Alerts">🔔'+(bell()?'<span class="dot">'+bell()+'</span>':'')+'</button>';
 if(back)$('bk').onclick=function(){S.sel=null;go()};$('bl').onclick=alerts}
function nav(){var n=$('nav');n.hidden=false;var T=[['home','🏠','Home'],['dr','📝','Drafts'],['sub','✅','Submitted'],['me','👤','Profile']];n.innerHTML=T.map(function(t){return '<button data-n="'+t[0]+'" class="'+(S.tab===t[0]?'on':'')+'"><i>'+t[1]+'</i>'+t[2]+'</button>'}).join('');n.onclick=function(e){var b=e.target.closest('button');if(b){S.tab=b.dataset.n;S.sel=null;go()}}}
function alerts(){var m=me(),L=FV.notifs('eng:'+m.id).slice(0,20),sh=document.createElement('div');sh.className='sheet';sh.innerHTML='<div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><b style="font:800 18px var(--f)">Alerts</b><button class="fbn s sm" id="shx">Close</button></div>'+(L.length?L.map(function(n){return '<div class="nt"><span style="color:'+(n.sev==='red'?'#A50E0E':n.sev==='amber'?'#8A5A00':'#176B3A')+'">●</span> '+esc(n.text)+'<br><small>'+esc(FV.when(n.at))+'</small></div>'}).join(''):'<p style="color:var(--mute)">No alerts yet.</p>')+'</div>';$('dev').appendChild(sh);BA.ls('ba3_fseen_'+m.id,String(Date.now()));sh.onclick=function(e){if(e.target===sh||e.target.id==='shx'){sh.remove();go()}}}
/* ---------- login with mobile number and OTP ---------- */
function login(){$('bar').hidden=true;$('nav').hidden=true;var demo=FV.dir().filter(function(m){return m.role==='field'});
 $('view').style.background='#fff';
 $('view').innerHTML='<div class="lg"><img src="img/app/icon-512.png" alt="BankAuctions Field"><h2>BankAuctions Field</h2><p>Verify properties on site. Sign in with the mobile number registered with BankAuctions.ai.</p></div>'+
 (S.msg?'<div class="err">'+esc(S.msg)+'</div>':'')+
 (S.otp?'<p style="margin:0 0 8px;text-align:center;color:var(--mute)">We sent a 6-digit OTP to +91 '+esc(S.ph.slice(0,5)+' '+S.ph.slice(5))+'</p><div class="ph" style="margin-bottom:12px"><span>OTP</span><input id="otp" inputmode="numeric" maxlength="6" placeholder="• • • • • •" autocomplete="one-time-code"></div><button class="fbn" id="vf" style="width:100%">Verify and sign in</button><p style="text-align:center;margin:12px 0 0"><button class="fbn s sm" id="chg">Change number</button></p><p style="text-align:center;color:var(--mute);font-size:12.5px;margin:12px 0 0">Prototype: the OTP is 123456.</p>':
  '<label class="fl" style="margin:0 0 6px">Mobile number</label><div class="ph" style="margin-bottom:12px"><span>+91</span><input id="mob" inputmode="numeric" maxlength="10" placeholder="98765 43210" value="'+esc(S.ph)+'"></div><button class="fbn" id="so" style="width:100%">Send OTP</button><p style="text-align:center;color:var(--mute);font-size:12.5px;margin:16px 0 4px">Demo field engineers (tap to fill)</p><div class="demo">'+demo.map(function(m){return '<button data-d="'+m.phone+'">'+esc(m.name)+(m.status!=='active'?' ('+FV.STL[m.status].toLowerCase()+')':'')+'</button>'}).join('')+'</div>')+
 (inst?'<p style="text-align:center;margin:18px 0 0"><button class="fbn s sm" id="ins">Install this app</button></p>':'');
 var v=$('view');v.onclick=function(e){var b=e.target.closest('button');if(!b)return;
  if(b.dataset.d){S.ph=b.dataset.d;$('mob').value=S.ph}
  else if(b.id==='so'){var ph=($('mob').value||'').replace(/\D/g,'');S.msg='';if(!/^[6-9]\d{9}$/.test(ph)){S.msg='Enter your 10-digit mobile number.';login();return}var m=FV.byPhone(ph);
   if(!m||m.role!=='field'){S.msg='This number is not registered as a field engineer. Ask your reporting manager to get you onboarded.';S.ph=ph;login();return}
   if(m.status!=='active'){S.msg=m.status==='suspended'?'This account is suspended. Contact Admin.':'This account has been deactivated. Contact Admin.';S.ph=ph;login();return}
   S.ph=ph;S.otp=true;login();setTimeout(function(){var o=$('otp');if(o)o.focus()},50)}
  else if(b.id==='vf'){var o=($('otp').value||'').trim();if(o!=='123456'){S.msg='That OTP is not right. The prototype OTP is 123456.';login();S.msg='';return}var m2=FV.byPhone(S.ph);S.id=m2.id;S.msg='';S.otp=false;BA.ls('ba3_fapp',S.id);S.tab='home';var al=BA.jget('ba3_audit',[]);al.push({who:m2.name,role:'Field engineer',what:'Signed in to the Android app',at:Date.now()});BA.jset('ba3_audit',al);go()}
  else if(b.id==='chg'){S.otp=false;S.msg='';login()}
  else if(b.id==='ins'&&inst){inst.prompt()}}}
/* ---------- home: everything pending, overdue and urgent highlighted ---------- */
function groups(open){var g={overdue:[],urgent:[],ret:[],ok:[]};open.forEach(function(x){var s=FV.sla(x.a);g[s.level==='overdue'?'overdue':x.a.ret?'ret':s.level==='urgent'?'urgent':'ok'].push(x)});return g}
function order(list){return list.sort(function(x,y){var sx=FV.sla(x.a),sy=FV.sla(y.a),dx=sx.reasons.length?-sx.reasons[0].over:(sx.next?sx.next.due:0),dy=sy.reasons.length?-sy.reasons[0].over:(sy.next?sy.next.due:0);return dx-dy})}
function home(){var m=me(),all=FV.mine(m.id),open=all.filter(function(x){return !x.a.sub&&!x.a.fin}),g=groups(open),c=FV.counts(open),mg=FV.get(m.manager),w=all.filter(function(x){return x.a.sub&&!x.a.fin}).length;
 chrome('Hi, '+m.name.split(' ')[0]);nav();$('view').style.background='#F6F6F9';
 var T=function(k,l,n,col){return '<button class="stt" data-f="'+k+'" style="background:'+col.bg+';color:'+col.tx+';border-left-color:'+col.bd+';'+(S.filter===k?'outline:2px solid '+col.bd:'')+'"><b>'+n+'</b><span>'+l+'</span></button>'};
 var h='<div class="stats">'+T('overdue','Overdue',g.overdue.length,FV.COL.overdue)+T('urgent','Urgent',g.urgent.length+g.ret.length,FV.COL.urgent)+T('ok','On track',g.ok.length,FV.COL.ok)+'<button class="stt" data-f="sub" style="background:#fff;color:#17171c;border-left-color:#1E8E3E;border:1px solid #ececf0;border-left:6px solid #1E8E3E"><b>'+w+'</b><span>With checker</span></button></div>';
 if(g.overdue.length)h+='<div class="bn" style="background:'+FV.COL.overdue.bg+';border-color:'+FV.COL.overdue.bd+';color:'+FV.COL.overdue.tx+'"><b>'+g.overdue.length+' visit'+(g.overdue.length>1?'s are':' is')+' overdue.</b> '+(mg?esc(mg.name)+', your manager, and ':'')+'Admin can see this. Update them today.</div>';
 else if(g.urgent.length)h+='<div class="bn" style="background:'+FV.COL.urgent.bg+';border-color:'+FV.COL.urgent.bd+';color:'+FV.COL.urgent.tx+'"><b>'+g.urgent.length+' deadline'+(g.urgent.length>1?'s':'')+' within 6 hours.</b></div>';
 h+='<div class="chips">'+[['all','All ('+open.length+')'],['accept','To accept ('+open.filter(function(x){return !x.a.ack}).length+')'],['sched','Scheduled ('+open.filter(function(x){return x.a.sched}).length+')']].map(function(f){return '<button data-ch="'+f[0]+'" class="'+(S.filter===f[0]?'on':'')+'">'+f[1]+'</button>'}).join('')+'</div>';
 var F=function(x){return S.filter==='accept'?!x.a.ack:S.filter==='sched'?!!x.a.sched:true},any=false;
 [['overdue','Overdue','overdue'],['ret','Returned by checker','urgent'],['urgent','Urgent','urgent'],['ok','On track','ok']].forEach(function(k){var L=order(g[k[0]].filter(F));if(S.filter==='overdue'&&k[0]!=='overdue'||S.filter==='urgent'&&k[0]!=='urgent'&&k[0]!=='ret'||S.filter==='ok'&&k[0]!=='ok')return;if(!L.length)return;any=true;var col=FV.COL[k[2]];h+='<div class="gh" style="color:'+col.tx+'"><i style="background:'+col.bd+'"></i>'+k[1]+' ('+L.length+')</div>'+L.map(function(x){return FV.card(x.p.id,x.a,false)}).join('')});
 if(!any)h+='<div class="card" style="text-align:center"><b style="font-size:17px">Nothing pending</b><br><span style="color:var(--mute)">New site visits show up here when Admin assigns them.</span></div>';
 $('view').innerHTML=h;
 $('view').onclick=function(e){var t=e.target.closest('[data-task]');if(t&&!e.target.closest('a')){S.sel=t.dataset.task;go();return}var f=e.target.closest('[data-f]');if(f){S.filter=S.filter===f.dataset.f?'all':f.dataset.f;if(S.filter==='sub'){S.tab='sub';S.filter='all'}go();return}var c2=e.target.closest('[data-ch]');if(c2){S.filter=c2.dataset.ch;go()}}}
/* ---------- one property ---------- */
function task(){var id=S.sel,m=me(),a=FV.asg()[id],p=FV.property(id);if(!a||a.eng!==m.id){S.sel=null;go();return}
 chrome(p.short+' · '+p.loc,true);nav();$('view').style.background='#F6F6F9';var b=a.br;
 $('view').innerHTML='<div class="fvr" style="margin:0 0 12px"><a class="fbn s sm" href="tel:+91'+esc(b.officerPhone)+'">📞 Branch</a><a class="fbn s sm" href="tel:+91'+esc(b.showPhone)+'">📞 On-site contact</a><a class="fbn s sm" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(b.loc)+'">🧭 Directions</a></div><div id="tk">'+FV.taskHtml(id)+FV.actionsHtml(id)+(a.sched||a.ret||a.sub?'<div id="fm"></div>':'<div class="fvn"><b>Accept and schedule first.</b> The report opens once your visit time is booked.</div>')+'</div>';
 FV.taskWire($('tk'),function(){go()});$('view').scrollTop=0;
 if($('fm'))FV.form($('fm'),id,{eng:m.id,onSubmit:function(){S.sel=null;S.tab='sub';go()}})}
function list(kind){var m=me(),all=FV.mine(m.id);chrome(kind==='dr'?'Drafts':'Submitted');nav();$('view').style.background='#F6F6F9';var L;
 if(kind==='dr'){L=FV.drafts(m.id).map(function(id){return {p:FV.property(id),a:FV.asg()[id]}}).filter(function(x){return x.p})}else L=all.filter(function(x){return x.a.sub||x.a.fin});
 $('view').innerHTML=(L.length?L.map(function(x){var d=FV.draft(x.p.id),n=FV.need(d),ok=n.filter(function(y){return y.ok}).length,q=FV.queue().filter(function(r){return r.id===x.p.id})[0];
  return kind==='dr'?'<div class="fcd" data-task="'+x.p.id+'" style="border-left-color:#2F6FE0"><div class="ft2"><b>'+esc(x.p.short)+' · '+esc(x.p.loc)+'</b><span class="fsl" style="background:#EAF3FF;color:#1F4AA8">Draft</span></div><div class="fm2">'+ok+' of '+n.length+' items ready · '+d.photos.length+' photos'+(d.upd?' · saved '+esc(FV.when(d.upd)):'')+'</div></div>':'<div class="fcd" data-task="'+x.p.id+'" style="border-left-color:'+(x.a.fin?'#1E8E3E':'#F29900')+'"><div class="ft2"><b>'+esc(x.p.short)+' · '+esc(x.p.loc)+'</b><span class="fsl" style="background:'+(x.a.fin?'#E6F6EC;color:#176B3A':'#FFF4DB;color:#8A5A00')+'">'+(x.a.fin?'Published':'With checker')+'</span></div><div class="fm2">Submitted '+esc(FV.when(x.a.sub))+(q&&q.hist.length>1?' · resubmitted':'')+'</div></div>'}).join(''):'<div class="card" style="text-align:center"><b style="font-size:17px">'+(kind==='dr'?'No drafts':'Nothing submitted yet')+'</b><br><span style="color:var(--mute)">'+(kind==='dr'?'Anything you start and leave unfinished is kept here.':'Reports you submit show here while the checker reviews them.')+'</span></div>');
 $('view').onclick=function(e){var t=e.target.closest('[data-task]');if(t){S.sel=t.dataset.task;go()}}}
function profile(){var m=me(),mg=FV.get(m.manager);chrome('Profile');nav();$('view').style.background='#F6F6F9';
 $('view').innerHTML='<div class="card" style="text-align:center">'+FV.avatar(m,84)+'<h3 style="font:800 21px var(--f);margin:10px 0 2px">'+esc(m.name)+'</h3><span style="color:var(--mute)">Field engineer · '+esc(m.state)+'</span></div><div class="card"><div class="srow"><span>Mobile</span><b>+91 '+m.phone.slice(0,5)+' '+m.phone.slice(5)+'</b></div><div class="srow"><span>Cities</span><b>'+esc(m.cities.map(FV.cl).join(', '))+'</b></div><div class="srow"><span>Reports to</span><b>'+(mg?esc(mg.name)+'<br>'+FV.tel(mg.phone):'Not assigned')+'</b></div></div><div class="card"><b>Deadlines</b><div class="srow"><span>Accept a new visit</span><b>within 24 hours</b></div><div class="srow"><span>Schedule the visit</span><b>within 12 hours of accepting</b></div><div class="srow"><span>Finish and submit</span><b>within 48 hours</b></div><p style="color:var(--mute);font-size:13px;margin:8px 0 0">Late visits are shown to your manager, Admin and Leadership.</p></div>'+(inst?'<button class="fbn s" id="ins" style="width:100%;margin-bottom:10px">Install this app</button>':'')+'<button class="fbn d" id="so" style="width:100%">Sign out</button><p style="text-align:center;color:var(--mute);font-size:12px;margin:14px 0 0">BankAuctions Field · prototype</p>';
 $('view').onclick=function(e){var b=e.target.closest('button');if(!b)return;if(b.id==='so'){BA.ls('ba3_fapp',null);S.id='';S.otp=false;S.ph='';go()}if(b.id==='ins'&&inst)inst.prompt()}}
function go(){FV.sweep();if(!me()){login();return}if(S.sel)return task();if(S.tab==='dr')return list('dr');if(S.tab==='sub')return list('sub');if(S.tab==='me')return profile();home()}
go();
/* keep countdowns fresh on the home list */
setInterval(function(){if(me()&&!S.sel&&S.tab==='home'&&!document.querySelector('.sheet')&&!(document.activeElement&&/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)))home()},60000);
})();
